// Package: Microsoft.Extensions.AI
// Install: dotnet add package Microsoft.Extensions.AI.OpenAI --version 9.*

using Microsoft.Extensions.AI;
using OpenAI;

public sealed class EmbeddingService
{
    private readonly IEmbeddingGenerator<string, Embedding<float>> _generator;

    public EmbeddingService(OpenAIClient openAIClient)
    {
        _generator = openAIClient.AsEmbeddingGenerator("text-embedding-3-small");
    }

    public async Task<Embedding<float>> GetEmbeddingAsync(
        string text,
        CancellationToken cancellationToken = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(text);

        try
        {
            return await _generator.GenerateAsync(
                new[] { new EmbeddingGenerationItem(text) },
                cancellationToken: cancellationToken);
        }
        catch (OperationCanceledException)
        {
            // Handle graceful cancellation
            throw;
        }
        catch (AIException ex)
        {
            // Log provider-specific failures
            Console.Error.WriteLine($"Embedding failed: {ex.Message}");
            throw;
        }
    }
}

// Usage example
var service = new EmbeddingService(new OpenAIClient(Environment.GetEnvironmentVariable("OPENAI_API_KEY")!));

Embedding<float> result = await service.GetEmbeddingAsync("The server returned a 500 error.");
Console.WriteLine($"Vector length: {result.Vector.Length}");
// Expected output: Vector length: 1536
